using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using TeatroSESI;
namespace Maracannes {
public sealed class AcervoRuntimeAudit:MonoBehaviour {
 const string B="Assets/Maracannes/Documentation/";readonly List<string> log=new List<string>();VisitaCentroSESI v;AcervoTravel travel;MuseumExperience m;bool failed;float start;
 IEnumerator Start(){if(!File.Exists(B+"acervo-test.request"))yield break;var mode=File.ReadAllText(B+"acervo-test.request").Trim();if(mode!="run"&&mode!="manual")yield break;File.WriteAllText(B+"acervo-test.request","running");v=GetComponent<VisitaCentroSESI>();if(!v)yield break;travel=GetComponent<AcervoTravel>();m=GetComponent<MuseumExperience>();start=Time.realtimeSinceStartup;yield return null;
 if(mode=="manual"){travel.SetPosition(new Vector3(12,.05f,-25.8f),90);File.WriteAllText(B+"acervo-test.request","manual-entry-ready");while(!travel.InAcervo)yield return null;while(travel.Busy)yield return null;travel.SetPosition(new Vector3(17.6f,.05f,-25.8f),-90);File.WriteAllText(B+"acervo-test.request","manual-exit-ready");yield break;}
 Check(v.transform.position.z< -30,"Teatro original inicia no exterior");yield return Walk(0,-27);yield return Walk(0,-26.2f);yield return Walk(-2.4f,-25.9f);var ticket=m.points.First(p=>p&&p.action==MuseumAction.Ticket);Check(m.Interact(ticket)&&m.IssueTicket(),"Bilheteria original emite ingresso");m.Close();yield return Walk(0,-26.2f);yield return Walk(2.5f,-24.3f);yield return Walk(5,-24.3f);yield return Walk(5,-23.8f);yield return Walk(12,-23.8f);yield return Walk(12,-25.8f);
 var entry=FindObjectsByType<AcervoDoor>(FindObjectsInactive.Exclude).First(d=>d.enterAcervo);Check(travel.UseDoor(entry),"Porta do saguão inicia transição");yield return WaitTravel();Check(travel.InAcervo&&!SceneManager.GetSceneByPath(AcervoTravel.Theater).isLoaded,"Acervo carregado sozinho; teatro descarregado");Check(m.enabled&&m.points.Length==3,"Somente painéis históricos disponíveis na interface do acervo");Check(FindObjectsByType<VisitaCentroSESI>(FindObjectsInactive.Exclude).Length==1,"Um único visitante após entrada");
 var museum=SceneManager.GetSceneByPath(AcervoTravel.Acervo);var all=museum.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var posters=all.Where(t=>t.GetComponent<MaracannesExhibit>()).Select(t=>t.GetComponent<MaracannesExhibit>()).ToArray();Check(all.Count(t=>t.GetComponent<MaracannesRoom>())==4,"Exatamente quatro salas");Check(posters.Length==43&&posters.Count(p=>p.room==2)==30,"43 materiais incluídos, todos os 30 na sala 2");Check(all.Count(t=>t.GetComponent<MuseumPoint>())==3,"Somente os três painéis históricos interativos");Check(all.Count(t=>t.GetComponent<AcervoDoor>())==1,"Uma porta de saída no acervo");Check(all.Count(t=>t.GetComponent<AcervoSculpture>())>=36,"36 novas composições de esculturas e móbiles");foreach(var p in posters){var texts=p.GetComponentsInChildren<TextMesh>(true);Check(p.room==2?texts.Length==1&&texts[0].name=="Identificação":texts.Length==0,"Cartaz estático e legenda permitida: "+p.catalogId);Check(!p.GetComponentsInChildren<MuseumPoint>(true).Any()&&!p.GetComponentsInChildren<AcervoDoor>(true).Any(),"Sem scripts de interação: "+p.catalogId);}
 yield return Shot("Acervo_Runtime_Sala1.png");yield return Walk(28,-25.8f);yield return Walk(35,-25.8f);yield return Shot("Acervo_Runtime_Sala2.png");yield return Walk(36,-17);yield return Walk(43,-15);yield return Walk(43,-9.3f);yield return Shot("Acervo_Runtime_Sala3.png");yield return Walk(43,-7);yield return Walk(35,-7);yield return Walk(35,-4);yield return Walk(29,-4);yield return Shot("Acervo_Runtime_Sala4.png");yield return Walk(27,-8.5f);yield return Walk(25.8f,-10.8f);yield return Walk(24,-15);yield return Walk(24,-19.2f);yield return Walk(18.4f,-19.2f);yield return Walk(18.4f,-25.8f);yield return Walk(17.6f,-25.8f);
 var exit=FindObjectsByType<AcervoDoor>(FindObjectsInactive.Exclude).First(d=>!d.enterAcervo);Check(travel.UseDoor(exit),"Saída inicia retorno");yield return WaitTravel();Check(!travel.InAcervo&&SceneManager.GetSceneByPath(AcervoTravel.Theater).isLoaded,"Retorno ao teatro, acervo descarregado");Check(FindObjectsByType<VisitaCentroSESI>(FindObjectsInactive.Exclude).Length==1,"Sem duplicação de visitante no retorno");Check(m.ticketIssued&&m.issuedCount==1&&m.enabled,"Estado do ingresso preservado e interface original restaurada");yield return Walk(12,-23.8f);yield return Walk(5,-23.8f);yield return Walk(5,-24.3f);yield return Walk(2.5f,-24.3f);yield return Walk(0,-22);yield return Walk(0,-16.6f);var gate=m.points.First(p=>p&&p.action==MuseumAction.Gate);Check(m.Interact(gate)&&m.ticketValidated,"Ingresso continua válido na porta original");yield return new WaitForSeconds(1.5f);yield return Walk(0,-8);yield return Walk(0,-4);yield return Walk(0,0);Check(v.transform.position.y>.9f,"Palco original continua acessível");Finish();
 }
 IEnumerator WaitTravel(){float end=Time.realtimeSinceStartup+20;while(travel.Busy&&Time.realtimeSinceStartup<end)yield return null;Check(!travel.Busy,"Transição conclui sem bloqueio permanente");}
 IEnumerator Walk(float x,float z){if(failed)yield break;v.autoWalking=true;v.autoTarget=new Vector3(x,0,z);float end=Time.realtimeSinceStartup+18;while(Vector2.Distance(new Vector2(v.transform.position.x,v.transform.position.z),new Vector2(x,z))>.24f&&Time.realtimeSinceStartup<end)yield return null;v.autoWalking=false;Check(Vector2.Distance(new Vector2(v.transform.position.x,v.transform.position.z),new Vector2(x,z))<=.24f&&v.transform.position.y>-.2f,"Caminhada com colisões: "+x+", "+z+" → "+v.transform.position.ToString("F2"));}
 IEnumerator Shot(string name){if(failed)yield break;v.cameraVisita.transform.localRotation=Quaternion.identity;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(B+"Evidencias/"+name);yield return null;}
 void Check(bool ok,string s){log.Add((ok?"PASS ":"FAIL ")+s);if(!ok)failed=true;File.WriteAllLines(B+"acervo-progresso.txt",log);}
 void Finish(){v.autoWalking=false;File.WriteAllLines(B+"acervo-runtime.txt",new[]{(failed?"FAIL":"PASS")+" Teste real no Editor: portas, carga/descarga de cenas, acervo estático, circulação e teatro · "+(Time.realtimeSinceStartup-start).ToString("F1")+" s"}.Concat(log));File.WriteAllText(B+"acervo-test.request","done");
 #if UNITY_EDITOR
 UnityEditor.EditorApplication.delayCall+=()=>UnityEditor.EditorApplication.isPlaying=false;
 #endif
 }
}
}
